tasks.check:
set -o pipefail
R=/home/bcorfman/dev/ringer-work/phase2-prep/scout-report.md
[ -s "$R" ] || { echo "WHY: report missing or empty: $R"; exit 1; }
for q in Q1 Q2 Q3 Q4 Q5 Q6; do grep -q "$q" "$R" || { echo "WHY: report does not answer $q"; exit 1; }; done
[ $(wc -w < "$R") -ge 250 ] || { echo "WHY: report too short"; exit 1; }
grep -Eq '[a-z_/]+\.(py|yaml|md):[0-9]+' "$R" || { echo "WHY: report has no file:line evidence"; exit 1; }
CH=$(git status --porcelain | grep -v '^?? .venv' | wc -l); [ "$CH" -eq 0 ] || { echo "WHY: scout changed files"; git status --porcelain; exit 1; }
echo ok
